function stateSession(ref){return sessionSchedule.find(s=>s.code===ref||s.name===ref);}
function stateIndicator(ref,compact=false){const session=stateSession(ref);if(!session)return "";const slug=session.status.toLowerCase().replaceAll(" ","-");return `<span class="state-session-indicator ${slug} ${compact?"compact":""}" title="${escapeHtml(session.name)}: ${session.status}. ${escapeHtml(session.nextDate)}"><i></i>${compact?session.status.replace(" session",""):session.status}</span>`;}
function annotateStateMentions(text){let output=escapeHtml(text);bills.forEach(bill=>{output=output.replaceAll(escapeHtml(bill.id),objectRef("bill",bill.id,escapeHtml(bill.id),"inline-object-title"));});sessionSchedule.forEach(session=>{output=output.replaceAll(session.name,`${session.name} ${stateIndicator(session.code,true)}`);});return output;}
function stateRefForObject(type,x){
  if(type==="bill")return x.state;
  if(type==="legislator"||type==="committee"||type==="organization")return x.jurisdiction;
  if(type==="jurisdiction")return x.name;
  if(type==="session"||type==="chamber")return getObject("jurisdiction",x.jurisdiction)?.name;
  if(type==="hearing")return getObject("committee",x.committee)?.jurisdiction;
  if(["amendment","bill-version","vote","position","document","engagement","impact-assessment"].includes(type)){const billId=x.bill;return billId?getObject("bill",billId)?.state:undefined;}
}

