function renderSessionDialog(){
  const statuses=["All","In session","Special session","Recess","Adjourned","Out of session"];
  document.querySelector("#sessionModalContent").innerHTML=`<div class="session-modal-head"><div><span class="prototype-label">PROTOTYPE SCHEDULE DATA</span><h2>50-state session calendar</h2><p>Current legislative status, deadlines, chamber calendars, and the next date that matters.</p></div><button data-close-sessions aria-label="Close session calendar">×</button></div>
    <div class="session-summary">${statuses.slice(1).map(status=>`<div><strong>${sessionSchedule.filter(s=>s.status===status).length}</strong><span>${status}</span></div>`).join("")}</div>
    <div class="session-toolbar"><label><span>⌕</span><input id="sessionSearch" placeholder="Find a state"></label><div class="session-filters">${statuses.map(status=>`<button class="${sessionFilter===status?"active":""}" data-session-filter="${status}">${status}</button>`).join("")}</div></div>
    <div class="session-list-head"><span>State</span><span>Status</span><span>Session dates</span><span>Next important date</span><span>Updated</span><span></span></div>
    <div class="session-list" id="sessionList">${sessionSchedule.map(s=>`<details class="session-row" data-session-status="${s.status}" data-session-search="${(s.name+" "+s.code+" "+s.status).toLowerCase()}"><summary><span class="session-state"><b>${s.code}</b><strong>${s.name}</strong></span><span><i class="session-status ${s.status.toLowerCase().replaceAll(" ","-")}"></i>${s.status}</span><span>${s.convene}–${s.adjourn}</span><span>${s.nextDate}</span><span>${s.updated}</span><em>⌄</em></summary><div class="session-details"><div><small>CONVENES</small><b>${s.convene}</b></div><div><small>ADJOURNS</small><b>${s.adjourn}</b></div><div><small>INTRODUCTION DEADLINE</small><b>${s.introduction}</b></div><div><small>CROSSOVER DEADLINE</small><b>${s.crossover}</b></div><div><small>PREFILING PERIOD</small><b>${s.prefiling}</b></div><div><small>NEXT IMPORTANT DATE</small><b>${s.nextDate}</b></div><div class="wide"><small>CHAMBER CALENDARS</small><div class="chamber-calendars">${s.chambers.map(c=>`<span><b>${c.name}</b>${c.calendar}</span>`).join("")}</div></div><div class="wide"><small>SPECIAL-SESSION ANNOUNCEMENTS</small><p>${s.announcement}</p></div><footer><span>Source: <b>${s.source}</b></span><span>Last updated: <b>${s.updated}</b></span></footer></div></details>`).join("")}</div>
    <div class="session-disclaimer"><span>ⓘ</span><p>This prototype uses representative schedule data. Production dates and status will come from verified legislative sources with source-level timestamps.</p></div>`;
  document.querySelector("#sessionModal").showModal();filterSessionRows();
}
function filterSessionRows(){const q=document.querySelector("#sessionSearch")?.value.toLowerCase()||"";document.querySelectorAll(".session-row").forEach(row=>{row.hidden=(sessionFilter!=="All"&&row.dataset.sessionStatus!==sessionFilter)||!row.dataset.sessionSearch.includes(q);});}

const objectConfig={
  bill:{label:"Bill",icon:"▤"},legislator:{label:"Legislator",icon:"♙"},client:{label:"Client",icon:"◎"},issue:{label:"Issue",icon:"◫"},theme:{label:"Theme",icon:"◈"},keyword:{label:"Keyword",icon:"#"},user:{label:"User",icon:"●"},report:{label:"Report",icon:"▥"},"client-profile":{label:"Client profile",icon:"◌"},"impact-assessment":{label:"Impact assessment",icon:"✦"},committee:{label:"Committee",icon:"⌂"},hearing:{label:"Hearing",icon:"◇"},amendment:{label:"Amendment",icon:"±"},"bill-version":{label:"Bill version",icon:"≡"},vote:{label:"Vote",icon:"✓"},jurisdiction:{label:"Jurisdiction",icon:"◉"},session:{label:"Session",icon:"◷"},chamber:{label:"Chamber",icon:"▥"},contact:{label:"Contact",icon:"●"},organization:{label:"Organization",icon:"▧"},engagement:{label:"Engagement",icon:"↔"},position:{label:"Position",icon:"◆"},document:{label:"Document",icon:"▱"},"report-template":{label:"Report template",icon:"▦"},"saved-search":{label:"Saved search",icon:"⌕"}
};
function getObject(type,id){return collectionFor(type).find(x=>String(x.id)===String(id));}
function objectName(type,x){return type==="bill"?`${x.id} · ${x.title}`:type==="keyword"?x.term:x.name;}
function objectSubtitle(type,x){const values={bill:()=>`${x.state} · ${x.status}`,legislator:()=>`${x.party} · ${x.chamber} · ${x.district}`,client:()=>`${x.industry} · Active client`,issue:()=>`${x.type} workspace`,theme:()=>`${x.issues.length} related issue${x.issues.length===1?"":"s"}`,keyword:()=>`${x.match} · ${x.hits} matches this week`,user:()=>x.role,report:()=>`${x.type} · ${x.status}`,"client-profile":()=>`v${x.version} · ${x.completeness}% complete · ${x.status}`,"impact-assessment":()=>`${x.materiality} materiality · ${x.direction} · ${x.reviewStatus}`,committee:()=>`${x.jurisdiction} · ${x.chamber}`,hearing:()=>`${x.date} · ${x.status}`,amendment:()=>`${x.status} · ${x.date}`,"bill-version":()=>`${x.status} · ${x.versionDate}`,vote:()=>`${x.result} · ${x.date}`,jurisdiction:()=>`${x.status} · ${x.trackedBills} tracked bills`,session:()=>`${x.status} · ${x.start}–${x.end}`,chamber:()=>`${x.members} members · ${x.partyControl} control · ${x.status}`,contact:()=>`${x.role} · ${x.organization}`,organization:()=>`${x.type} · ${x.jurisdiction}`,engagement:()=>`${x.type} · ${x.date} · ${x.status}`,position:()=>`${x.stance} · ${x.status}`,document:()=>`${x.type} · ${x.version}`,"report-template":()=>`${x.sections} sections · Updated ${x.updated}`,"saved-search":()=>`${x.results} results · Owned by ${x.owner}`};return values[type]?.()||"";}
function objectSummary(type,x){const values={bill:()=>x.summary,legislator:()=>`${x.name} serves in the ${x.jurisdiction} ${x.chamber} and is connected to ${bills.filter(b=>b.sponsor===x.name).length} tracked bill.`,client:()=>`${x.name} is tracking ${x.bills} bills across ${x.issues.length} issue workspace${x.issues.length===1?"":"s"}.`,issue:()=>x.description,theme:()=>x.description,keyword:()=>`Tracking “${x.term}” using ${x.match.toLowerCase()} matching. ${x.hits} relevant matches were found in the last seven days.`,user:()=>`${x.name} collaborates across assigned clients, issues, reports, and legislative actions.`,report:()=>`A ${x.type.toLowerCase()} for ${x.client}, assembled from live tracked bills and analysis.`,"client-profile":()=>`${x.client} operates in ${x.industry}. This versioned context is used to retrieve evidence and evaluate potential legislative impact.`,"impact-assessment":()=>`${x.materiality} ${x.direction.toLowerCase()} impact is ${x.likelihood.toLowerCase()} over the ${x.timeHorizon.toLowerCase()}. ${x.recommendation}`,committee:()=>`Tracks ${x.bills.length} relevant bill and ${x.members} committee members. ${x.chair} serves as chair.`,hearing:()=>`Scheduled at ${x.location}. Preparation, testimony, attendees, and follow-up actions stay connected here.`,amendment:()=>x.summary,"bill-version":()=>x.summary,vote:()=>`The recorded outcome was ${x.result}. Individual member votes and team analysis can be attached here.`,jurisdiction:()=>`${x.name} currently has ${x.trackedBills} bills tracked by your organization.`,session:()=>`The active legislative period runs from ${x.start} through ${x.end}.`,chamber:()=>`${x.name} has ${x.members} members and is currently under ${x.partyControl.toLowerCase()} control.`,contact:()=>`${x.name} is a ${x.role} with ${x.organization}.`,organization:()=>`A ${x.type.toLowerCase()} operating in ${x.jurisdiction}.`,engagement:()=>`A ${x.type.toLowerCase()} connected to client work, policy context, participants, notes, and follow-up actions.`,position:()=>x.summary,document:()=>`${x.name} is the ${x.version} ${x.type.toLowerCase()} and was last updated ${x.updated}.`,"report-template":()=>x.description,"saved-search":()=>`Runs “${x.query}” and currently returns ${x.results} relevant records.`};return values[type]?.()||"";}
function relatedObjects(type,x){
  let refs=[];
  const add=(t,id,label,meta)=>id!==undefined&&refs.push({type:t,id,label,meta});
  if(type==="client"){state.clientProfiles.filter(p=>p.client===x.name).forEach(p=>add("client-profile",p.id,p.name,`${p.completeness}% complete`));state.impactAssessments.filter(a=>a.client===x.name).forEach(a=>add("impact-assessment",a.id,a.name,`${a.materiality} · ${a.reviewStatus}`));x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));state.themes.filter(t=>t.issues.some(i=>x.issues.includes(i))).slice(0,3).forEach(t=>add("theme",t.id,t.name,"Theme"));bills.filter(b=>b.clients.includes(x.name)).forEach(b=>add("bill",b.id,b.id,b.status));state.reports.filter(r=>r.client===x.name).forEach(r=>add("report",r.id,r.name,r.status));state.positions.filter(p=>p.client===x.name).forEach(p=>add("position",p.id,p.name,p.stance));state.engagements.filter(g=>g.client===x.name).forEach(g=>add("engagement",g.id,g.name,g.date));state.documents.filter(d=>d.client===x.name).forEach(d=>add("document",d.id,d.name,d.version));add("user",idByName("user",x.owner),x.owner,"Relationship owner");}
  if(type==="issue"){x.clients.forEach(n=>add("client",idByName("client",n),n,"Client"));x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));bills.filter(b=>b.issues.includes(x.name)).forEach(b=>add("bill",b.id,b.id,b.status));state.keywords.filter(k=>k.group===x.name).forEach(k=>add("keyword",k.id,k.term,`${k.hits} matches`));state.savedSearches.filter(s=>s.issue===x.name).forEach(s=>add("saved-search",s.id,s.name,`${s.results} results`));state.positions.filter(p=>p.issue===x.name).forEach(p=>add("position",p.id,p.name,p.stance));}
  if(type==="theme"){x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));state.keywords.filter(k=>k.themes.includes(x.name)).forEach(k=>add("keyword",k.id,k.term,`${k.hits} matches`));bills.filter(b=>b.themes.includes(x.name)).forEach(b=>add("bill",b.id,b.id,b.status));state.impactAssessments.filter(a=>a.themes.includes(x.name)).forEach(a=>add("impact-assessment",a.id,a.name,a.materiality));const clients=[...new Set(x.issues.flatMap(i=>state.issues.find(issue=>issue.name===i)?.clients||[]))];clients.forEach(n=>add("client",idByName("client",n),n,"Client"));}
  if(type==="bill"){state.impactAssessments.filter(a=>a.bill===x.id).forEach(a=>add("impact-assessment",a.id,a.name,`${a.materiality} · ${a.reviewStatus}`));x.clients.forEach(n=>add("client",idByName("client",n),n,"Client"));x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));add("legislator",idByName("legislator",x.sponsor),x.sponsor,"Sponsor");state.committees.filter(c=>c.bills.includes(x.id)).forEach(c=>add("committee",c.id,c.name,"Committee"));state.hearings.filter(h=>h.bills.includes(x.id)).forEach(h=>add("hearing",h.id,h.name,h.date));state.billVersions.filter(v=>v.bill===x.id).forEach(v=>add("bill-version",v.id,v.name,v.status));state.amendments.filter(a=>a.bill===x.id).forEach(a=>add("amendment",a.id,a.name,a.status));state.votes.filter(v=>v.bill===x.id).forEach(v=>add("vote",v.id,v.name,v.result));state.positions.filter(p=>p.bill===x.id).forEach(p=>add("position",p.id,p.name,p.stance));state.documents.filter(d=>d.bill===x.id).forEach(d=>add("document",d.id,d.name,d.version));state.reports.filter(r=>r.bills.includes(x.id)).forEach(r=>add("report",r.id,r.name,"Report"));}
  if(type==="keyword"){if(x.groupType!=="Standalone")add(x.groupType.toLowerCase(),idByName(x.groupType.toLowerCase(),x.group),x.group,x.groupType);x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));}
  if(type==="user")state.clients.filter(c=>c.owner===x.name).forEach(c=>add("client",c.id,c.name,"Assigned client"));
  if(type==="legislator"){bills.filter(b=>b.sponsor===x.name).forEach(b=>add("bill",b.id,b.id,b.title));state.committees.filter(c=>c.chair===x.name).forEach(c=>add("committee",c.id,c.name,"Committee chair"));}
  if(type==="report"){add("client",idByName("client",x.client),x.client,"Client");x.issues.forEach(n=>add("issue",idByName("issue",n),n,"Issue"));state.themes.filter(t=>t.issues.some(i=>x.issues.includes(i))).slice(0,3).forEach(t=>add("theme",t.id,t.name,"Theme"));x.bills.forEach(id=>add("bill",id,id,getObject("bill",id)?.status));state.impactAssessments.filter(a=>a.client===x.client&&x.bills.includes(a.bill)).forEach(a=>add("impact-assessment",a.id,a.name,a.reviewStatus));add("report-template","weekly-client-update","Weekly Client Update","Template");}
  if(type==="client-profile"){add("client",idByName("client",x.client),x.client,"Client");state.impactAssessments.filter(a=>a.profile===x.id).forEach(a=>add("impact-assessment",a.id,a.name,a.reviewStatus));}
  if(type==="impact-assessment"){add("client",idByName("client",x.client),x.client,"Client");add("client-profile",x.profile,getObject("client-profile",x.profile)?.name,"Profile input");add("bill",x.bill,x.bill,"Bill");if(x.billVersion)add("bill-version",x.billVersion,getObject("bill-version",x.billVersion)?.name,"Bill version");x.themes.forEach(n=>add("theme",idByName("theme",n),n,"Theme"));add("user",idByName("user",x.reviewer),x.reviewer,"Reviewer");}
  if(type==="committee"){add("jurisdiction",idByName("jurisdiction",x.jurisdiction),x.jurisdiction,"Jurisdiction");add("chamber",idByName("chamber",`${x.jurisdiction} State ${x.chamber}`),`${x.jurisdiction} ${x.chamber}`,"Chamber");add("legislator",idByName("legislator",x.chair),x.chair,"Chair");x.bills.forEach(id=>add("bill",id,id,getObject("bill",id)?.status));state.hearings.filter(h=>h.committee===x.id).forEach(h=>add("hearing",h.id,h.name,h.date));state.contacts.filter(c=>c.organization.includes(x.jurisdiction)).forEach(c=>add("contact",c.id,c.name,c.role));}
  if(type==="hearing"){add("committee",x.committee,getObject("committee",x.committee)?.name,"Committee");x.bills.forEach(id=>add("bill",id,id,getObject("bill",id)?.title));}
  if(type==="amendment"){add("bill",x.bill,x.bill,getObject("bill",x.bill)?.title);state.documents.filter(d=>d.bill===x.bill).forEach(d=>add("document",d.id,d.name,d.version));}
  if(type==="bill-version"){add("bill",x.bill,x.bill,getObject("bill",x.bill)?.title);state.amendments.filter(a=>a.bill===x.bill).forEach(a=>add("amendment",a.id,a.name,a.status));}
  if(type==="vote"){add("bill",x.bill,x.bill,getObject("bill",x.bill)?.title);if(x.committee)add("committee",x.committee,getObject("committee",x.committee)?.name,"Committee");}
  if(type==="jurisdiction")state.sessions.filter(s=>s.jurisdiction===x.id).forEach(s=>add("session",s.id,s.name,s.status));
  if(type==="session")add("jurisdiction",x.jurisdiction,getObject("jurisdiction",x.jurisdiction)?.name,"Jurisdiction");
  if(type==="chamber"){add("jurisdiction",x.jurisdiction,getObject("jurisdiction",x.jurisdiction)?.name,"Jurisdiction");state.committees.filter(c=>x.name.includes(c.jurisdiction)&&x.name.includes(c.chamber)).forEach(c=>add("committee",c.id,c.name,"Committee"));}
  if(type==="contact")state.engagements.filter(g=>g.contacts.includes(x.id)).forEach(g=>add("engagement",g.id,g.name,g.date));
  if(type==="organization"&&x.id==="california-assembly"){add("jurisdiction","ca","California","Jurisdiction");state.committees.filter(c=>c.jurisdiction==="California").forEach(c=>add("committee",c.id,c.name,"Committee"));}
  if(type==="engagement"){add("client",idByName("client",x.client),x.client,"Client");add("issue",idByName("issue",x.issue),x.issue,"Issue");add("bill",x.bill,x.bill,"Bill");x.contacts.forEach(id=>add("contact",id,getObject("contact",id)?.name,"Participant"));}
  if(type==="position"){add("client",idByName("client",x.client),x.client,"Client");add("issue",idByName("issue",x.issue),x.issue,"Issue");add("bill",x.bill,x.bill,"Bill");}
  if(type==="document"){if(x.client)add("client",idByName("client",x.client),x.client,"Client");if(x.bill)add("bill",x.bill,x.bill,"Bill");}
  if(type==="report-template")state.reports.filter(r=>r.type.includes("Weekly")||x.id==="session-recap"&&r.type==="Session report").forEach(r=>add("report",r.id,r.name,r.status));
  if(type==="saved-search"){add("issue",idByName("issue",x.issue),x.issue,"Issue");add("user",idByName("user",x.owner),x.owner,"Owner");}
  return refs.slice(0,12);
}
function renderMentionText(text){let output=escapeHtml(text);state.users.forEach(u=>{output=output.replaceAll(`@${u.name}`,`<button class="mention" data-object-type="user" data-object-id="${u.id}">@${u.name}</button>`);});return output;}
function renderIntelligenceDetails(type,x){
  if(type==="client-profile")return `<section class="ai-detail-card profile-detail"><div class="ai-detail-head"><span>✦ AI CONTEXT PROFILE</span><b>${x.completeness}% complete</b></div><div class="profile-completeness"><i style="--complete:${x.completeness}%"></i></div><div class="profile-groups"><div><small>INDUSTRY</small><p>${escapeHtml(x.industry)}</p></div><div><small>MARKETS</small><p>${x.markets.map(v=>`<span>${escapeHtml(v)}</span>`).join("")}</p></div><div><small>PRODUCTS & SERVICES</small><p>${x.products.map(v=>`<span>${escapeHtml(v)}</span>`).join("")}</p></div><div><small>KEY COMPETENCIES</small><p>${x.competencies.map(v=>`<span>${escapeHtml(v)}</span>`).join("")}</p></div><div><small>REGULATORY EXPOSURE</small><p>${x.regulatoryExposure.map(v=>`<span>${escapeHtml(v)}</span>`).join("")}</p></div><div><small>STRATEGIC PRIORITIES</small><p>${x.priorities.map(v=>`<span>${escapeHtml(v)}</span>`).join("")}</p></div></div><footer><span>Sources: ${x.sources.map(escapeHtml).join(" · ")}</span><b>Last reviewed ${x.lastReviewed}</b></footer></section>`;
  if(type==="impact-assessment")return `<section class="assessment-detail"><div class="assessment-review ${x.reviewStatus.toLowerCase().replaceAll(" ","-")}"><div><span>✦ AI-GENERATED ASSESSMENT</span><b>${x.reviewStatus}</b><p>Review the supporting evidence before using this analysis in client advice.</p></div><div>${x.reviewStatus!=="Approved"?`<button data-assessment-decision="Approved" data-id="${x.id}">Approve</button>`:""}<button data-assessment-decision="Dismissed" data-id="${x.id}">Dismiss</button></div></div><div class="assessment-metrics"><div><small>MATERIALITY</small><b class="impact-${x.materiality.toLowerCase()}">${x.materiality}</b></div><div><small>DIRECTION</small><b>${x.direction}</b></div><div><small>LIKELIHOOD</small><b>${x.likelihood}</b></div><div><small>CONFIDENCE</small><b>${x.confidence}%</b></div><div><small>TIME HORIZON</small><b>${x.timeHorizon}</b></div></div><div class="affected-areas"><small>AFFECTED AREAS</small>${x.affectedAreas.map(a=>`<span>${escapeHtml(a)}</span>`).join("")}</div><div class="finding-list"><div class="finding-title"><h3>Findings and evidence</h3><span>${x.findings.length} findings</span></div>${x.findings.map(f=>`<article><span>${escapeHtml(f.category)}</span><h4>${escapeHtml(f.title)}</h4><p>${escapeHtml(f.detail)}</p><div>${f.evidence.map(evidenceRef).join("")}</div></article>`).join("")}</div><div class="assessment-recommendation"><small>RECOMMENDED RESPONSE</small><p>${escapeHtml(x.recommendation)}</p></div><details class="assessment-assumptions"><summary>Assumptions and provenance</summary><div><small>ASSUMPTIONS</small>${x.assumptions.map(a=>`<p>• ${escapeHtml(a)}</p>`).join("")}<small>GENERATION DETAILS</small><p>Model: ${escapeHtml(x.model)} · Prompt: ${escapeHtml(x.promptVersion)}</p><p>Profile: ${escapeHtml(x.profile)} · Generated ${escapeHtml(x.generated)}</p></div></details></section>`;
  return "";
}
function billHistoryEvents(bill){const amendment=state.amendments.find(item=>item.bill===bill.id),hearing=state.hearings.find(item=>item.bills.includes(bill.id)),vote=state.votes.find(item=>item.bill===bill.id);return [{date:bill.date,title:bill.status,detail:bill.statusType==="success"?"The measure completed its latest chamber or executive action.":"The bill’s current status was updated by the legislature.",tone:"current"},...(vote?[{date:vote.date,title:vote.name,detail:vote.result,tone:"vote"}]:[]),...(amendment?[{date:amendment.date,title:amendment.name,detail:amendment.summary,tone:"amendment"}]:[]),...(hearing?[{date:hearing.date.split(" · ")[0],title:hearing.name,detail:`${hearing.status} · ${hearing.location}`,tone:"hearing"}]:[]),{date:"Earlier this session",title:"Introduced and referred",detail:`The bill was introduced and referred for consideration in the ${bill.state} legislature.`,tone:"introduced"}].slice(0,6);}
function billNextEvent(bill){const hearing=state.hearings.find(item=>item.bills.includes(bill.id));return hearing?`${hearing.date} · ${hearing.name}`:stateSession(bill.state)?.nextDate||"No event scheduled";}
function renderBillClientRows(bill,compact=false){return bill.clients.map(client=>{const assessment=state.impactAssessments.find(item=>item.bill===bill.id&&item.client===client),position=state.positions.find(item=>item.bill===bill.id&&item.client===client);return `<button class="bill-client-impact" data-object-type="${assessment?"impact-assessment":"client"}" data-object-id="${assessment?.id||idByName("client",client)}"><span>${initials(client)}</span><div><b>${escapeHtml(client)}</b><small>${assessment?`${assessment.materiality} ${assessment.direction.toLowerCase()} impact · ${assessment.reviewStatus}`:"Impact assessment not started"}</small>${!compact&&position?`<em>${escapeHtml(position.stance)}</em>`:""}</div><i>→</i></button>`;}).join("");}
function renderBillPreviewDetails(bill){const events=billHistoryEvents(bill).slice(0,3),committee=state.committees.find(item=>item.bills.includes(bill.id));return `<section class="bill-preview-facts"><div><small>LATEST ACTION</small><b>${escapeHtml(bill.status)}</b><span>${escapeHtml(bill.date)}</span></div><div><small>NEXT EVENT</small><b>${escapeHtml(billNextEvent(bill))}</b></div><div><small>SPONSOR</small><b>${objectRef("legislator",idByName("legislator",bill.sponsor),bill.sponsor)}</b></div><div><small>COMMITTEE</small><b>${committee?objectRef("committee",committee.id,committee.name):"Not assigned"}</b></div></section><section class="drawer-section bill-preview-section"><div class="drawer-section-head"><h2>Client impact</h2><span>${bill.clients.length} clients</span></div><div class="bill-preview-clients">${renderBillClientRows(bill,true)}</div></section><section class="drawer-section bill-preview-section"><div class="drawer-section-head"><h2>Recent history</h2><button data-open-bill-tab="history" data-bill-id="${escapeHtml(bill.id)}">View full history</button></div><div class="bill-preview-history">${events.map((event,index)=>`<div class="${index===0?"latest":""}"><i></i><time>${escapeHtml(event.date)}</time><span><b>${escapeHtml(event.title)}</b><small>${escapeHtml(event.detail)}</small></span></div>`).join("")}</div></section>`;}
function billTabs(){return [["overview","Overview"],["history","History"],["text","Text & Versions"],["clients","Clients & Positions"],["stakeholders","Stakeholders"],["activity","Activity"]];}
function renderBillOverview(bill){const committee=state.committees.find(item=>item.bills.includes(bill.id)),hearing=state.hearings.find(item=>item.bills.includes(bill.id)),amendment=state.amendments.find(item=>item.bill===bill.id);return `<div class="bill-overview-grid"><main><section class="bill-page-card bill-summary-card"><span>PLAIN-LANGUAGE SUMMARY</span><h2>What this bill does</h2><p>${escapeHtml(bill.summary)}</p><div class="key-provisions"><h3>Key provisions</h3><ul><li>Establishes requirements for covered entities and regulated activities.</li><li>Creates implementation, disclosure, or compliance obligations.</li><li>Authorizes the responsible state agency to oversee enforcement.</li></ul></div>${amendment?`<div class="latest-change"><span>± LATEST VERSION CHANGE</span><p>${escapeHtml(amendment.summary)}</p>${objectRef("amendment",amendment.id,"Review amendment →")}</div>`:""}</section><section class="bill-page-card"><div class="bill-card-title"><div><span>✦</span><h2>Client impact</h2></div><small>${bill.clients.length} associated</small></div><div class="bill-page-clients">${renderBillClientRows(bill)}</div></section></main><aside><section class="bill-page-card bill-metadata"><h2>Bill details</h2><dl><div><dt>Jurisdiction</dt><dd>${jurisdictionRef(bill.state)} ${stateIndicator(bill.state,true)}</dd></div><div><dt>Session</dt><dd>${escapeHtml(state.sessions.find(s=>s.jurisdiction===bill.state.toLowerCase())?.name||"2025–2026 Regular Session")}</dd></div><div><dt>Sponsor</dt><dd>${objectRef("legislator",idByName("legislator",bill.sponsor),bill.sponsor)}</dd></div><div><dt>Committee</dt><dd>${committee?objectRef("committee",committee.id,committee.name):"Not assigned"}</dd></div><div><dt>Next event</dt><dd>${hearing?objectRef("hearing",hearing.id,hearing.date):escapeHtml(billNextEvent(bill))}</dd></div><div><dt>Source updated</dt><dd>${escapeHtml(bill.date)}</dd></div></dl></section><section class="bill-page-card"><h2>Classification</h2><div class="bill-classifications"><small>ISSUES</small>${bill.issues.map(name=>objectRef("issue",idByName("issue",name),name)).join("")}<small>THEMES</small>${bill.themes.map(name=>objectRef("theme",idByName("theme",name),name)).join("")}</div></section></aside></div>`;}
function renderBillHistoryTab(bill){return `<section class="bill-page-card full-history"><div class="bill-tab-heading"><div><h2>Legislative history</h2><p>Material actions, amendments, hearings, and votes in chronological order.</p></div><button>All event types ⌄</button></div><div class="full-history-list">${billHistoryEvents(bill).map((event,index)=>`<article class="${index===0?"current":""}"><time>${escapeHtml(event.date)}</time><i class="${event.tone}"></i><div><h3>${escapeHtml(event.title)}</h3><p>${escapeHtml(event.detail)}</p></div></article>`).join("")}</div></section>`;}
function renderBillTextTab(bill){const versions=state.billVersions.filter(item=>item.bill===bill.id),documents=state.documents.filter(item=>item.bill===bill.id),amendments=state.amendments.filter(item=>item.bill===bill.id);return `<div class="bill-text-grid"><section class="bill-page-card"><div class="bill-tab-heading"><div><h2>Current bill text</h2><p>Source text, versions, and section-level analysis.</p></div><button data-compare-versions>Compare versions</button></div><div class="mock-bill-text"><span>SECTION 1.</span><h3>${escapeHtml(bill.title)}</h3><p>${escapeHtml(bill.summary)} The responsible agency may adopt rules necessary to implement the requirements of this act.</p><mark>Covered entities must maintain records demonstrating compliance with applicable disclosure and operational requirements.</mark><p>Enforcement authority and effective dates shall apply as provided in the enacted version.</p></div></section><aside><section class="bill-page-card"><h2>Versions</h2><div class="version-list">${versions.length?versions.map(version=>objectRef("bill-version",version.id,`<b>${version.name}</b><small>${version.status}</small>`)).join(""):`<button><b>Introduced version</b><small>Current source text</small></button>`}</div></section><section class="bill-page-card"><h2>Amendments & documents</h2><div class="version-list">${[...amendments.map(item=>({type:"amendment",...item})),...documents.map(item=>({type:"document",...item}))].map(item=>objectRef(item.type,item.id,`<b>${item.name}</b><small>${item.status||item.version}</small>`)).join("")||"<p>No additional documents.</p>"}</div></section></aside></div>`;}
function renderBillClientsTab(bill){return `<section class="bill-page-card"><div class="bill-tab-heading"><div><h2>Clients & positions</h2><p>Client-specific applicability, impact, stance, owner, and next action.</p></div><button data-run-impact>✦ Run impact assessment</button></div><div class="client-position-table"><div class="client-position-head"><span>Client</span><span>Impact</span><span>Position</span><span>Owner</span><span>Next step</span></div>${bill.clients.map(client=>{const assessment=state.impactAssessments.find(item=>item.bill===bill.id&&item.client===client),position=state.positions.find(item=>item.bill===bill.id&&item.client===client),clientObject=state.clients.find(item=>item.name===client);return `<div class="client-position-row"><span>${objectRef("client",clientObject?.id,client)}</span><span>${assessment?objectRef("impact-assessment",assessment.id,`${assessment.materiality} · ${assessment.direction}`):"Not assessed"}</span><span>${position?objectRef("position",position.id,position.stance):"Undetermined"}</span><span>${objectRef("user",idByName("user",clientObject?.owner),clientObject?.owner||"Unassigned")}</span><span>${escapeHtml(assessment?.recommendation||"Assign impact review")}</span></div>`;}).join("")}</div></section>`;}
function renderBillStakeholdersTab(bill){const committees=state.committees.filter(item=>item.bills.includes(bill.id)),hearings=state.hearings.filter(item=>item.bills.includes(bill.id));return `<div class="stakeholder-grid"><section class="bill-page-card"><h2>Legislative stakeholders</h2><div class="stakeholder-list"><div><small>PRIMARY SPONSOR</small>${objectRef("legislator",idByName("legislator",bill.sponsor),`<b>${bill.sponsor}</b><span>Bill sponsor</span>`)}</div>${committees.map(item=>`<div><small>COMMITTEE</small>${objectRef("committee",item.id,`<b>${item.name}</b><span>Chair: ${item.chair}</span>`)}</div>`).join("")}</div></section><section class="bill-page-card"><h2>Hearings & engagements</h2><div class="stakeholder-list">${hearings.map(item=>`<div>${objectRef("hearing",item.id,`<b>${item.name}</b><span>${item.date} · ${item.status}</span>`)}</div>`).join("")||"<p>No hearing is currently scheduled.</p>"}${state.engagements.filter(item=>item.bill===bill.id).map(item=>`<div>${objectRef("engagement",item.id,`<b>${item.name}</b><span>${item.date}</span>`)}</div>`).join("")}</div></section></div>`;}
function renderBillActivityTab(bill){const key=`bill:${bill.id}`,actions=state.collaboration.actions[key]||[],comments=state.collaboration.comments[key]||[];return `<div class="bill-activity-grid"><section class="bill-page-card"><div class="bill-card-title"><h2>Open actions</h2><button data-page-add-action>＋ Add action</button></div><div class="page-action-list">${actions.length?actions.map(action=>`<label><input type="checkbox" data-action-toggle="${action.id}" data-key="${escapeHtml(key)}" ${action.status==="Done"?"checked":""}><span><b>${escapeHtml(action.title)}</b><small>${escapeHtml(action.assignee)} · Due ${escapeHtml(action.due)}</small></span><em>${action.priority}</em></label>`).join(""):`<p>No open actions.</p>`}</div></section><section class="bill-page-card"><div class="bill-card-title"><h2>Comments & decisions</h2><span>${comments.length}</span></div><div class="page-comment-list">${comments.map(comment=>`<article><span>${comment.initials}</span><div><b>${escapeHtml(comment.author)}</b><time>${escapeHtml(comment.time)}</time><p>${renderMentionText(comment.text)}</p></div></article>`).join("")||"<p>No comments yet.</p>"}</div></section></div>`;}
function renderBillWorkspace(){const bill=getObject("bill",parseHash().id)||bills[0],tab=state.billWorkspace.tab,tabs=billTabs();return `<div class="bill-workspace"><button class="bill-back" data-bill-back>← Back</button><header class="bill-page-head"><div class="bill-state-seal">${bill.state}</div><div><div class="bill-page-kicker"><span>${escapeHtml(bill.id)}</span>${stateIndicator(bill.state)}<span>${escapeHtml(bill.status)}</span></div><h1>${escapeHtml(bill.title)}</h1><p>${escapeHtml(bill.summary)}</p><div class="bill-page-tags">${bill.issues.map(name=>objectRef("issue",idByName("issue",name),name)).join("")}</div></div><div class="bill-page-actions"><button class="button secondary" data-follow-object>☆ Follow</button><button class="button secondary" data-page-add-action>＋ Action</button><button class="button primary track-button">✓ Tracked</button></div></header><section class="bill-status-strip"><div><small>CURRENT STATUS</small><b>${escapeHtml(bill.status)}</b></div><div><small>LATEST ACTION</small><b>${escapeHtml(bill.date)}</b></div><div><small>NEXT EVENT</small><b>${escapeHtml(billNextEvent(bill))}</b></div><div><small>SPONSOR</small><b>${objectRef("legislator",idByName("legislator",bill.sponsor),bill.sponsor)}</b></div></section><nav class="bill-tabs">${tabs.map(([id,label])=>`<button class="${tab===id?"active":""}" data-bill-tab="${id}">${label}</button>`).join("")}</nav><div class="bill-tab-content">${tab==="overview"?renderBillOverview(bill):tab==="history"?renderBillHistoryTab(bill):tab==="text"?renderBillTextTab(bill):tab==="clients"?renderBillClientsTab(bill):tab==="stakeholders"?renderBillStakeholdersTab(bill):renderBillActivityTab(bill)}</div></div>`;}
function renderObjectDrawer(type,id){
  const object=getObject(type,id);if(!object)return closeObjectDrawer(false);
  const config=objectConfig[type],key=`${type}:${id}`,relations=relatedObjects(type,object),actions=state.collaboration.actions[key]||[],comments=state.collaboration.comments[key]||[],priority=state.collaboration.priorities[key]||"Normal";
  const signalTitle=type==="bill"?"Why this matters":type==="report"?"Report scope":"At a glance";
  document.querySelector("#objectDrawerContent").innerHTML=`
    <div class="drawer-top"><span>${config.label}</span><div><button data-copy-object>Copy link</button><button class="drawer-close" data-close-object aria-label="Close details">×</button></div></div>
    <div class="object-heading"><span class="object-type-icon ${type}">${config.icon}</span><div><p>${config.label.toUpperCase()}</p><h1>${escapeHtml(objectName(type,object))}</h1><div class="object-subtitle"><span>${escapeHtml(objectSubtitle(type,object))}</span>${stateRefForObject(type,object)?stateIndicator(stateRefForObject(type,object)):""}</div></div></div>
    <div class="object-controls"><label>Priority<select data-object-priority data-key="${escapeHtml(key)}"><option ${priority==="Low"?"selected":""}>Low</option><option ${priority==="Normal"?"selected":""}>Normal</option><option ${priority==="Medium"?"selected":""}>Medium</option><option ${priority==="High"?"selected":""}>High</option><option ${priority==="Critical"?"selected":""}>Critical</option></select></label><button data-follow-object>☆ Follow</button>${["issue","theme","client","keyword","client-profile"].includes(type)?`<button data-edit-object data-type="${type}" data-id="${escapeHtml(id)}">Edit</button>`:""}<button data-full-object data-type="${type}" data-id="${escapeHtml(id)}">Open full page ↗</button></div>
    <div class="drawer-scroll">
      <section class="signal-card"><span>✦</span><div><small>${signalTitle}</small><p>${escapeHtml(objectSummary(type,object))}</p></div></section>${renderIntelligenceDetails(type,object)}${type==="bill"?renderBillPreviewDetails(object):""}
      <section class="drawer-section"><div class="drawer-section-head"><h2>Related</h2><span>${relations.length} objects</span></div><div class="relationship-grid">${relations.length?relations.map(r=>`<button data-object-type="${r.type}" data-object-id="${escapeHtml(r.id)}"><span class="relation-icon ${r.type}">${objectConfig[r.type].icon}</span><div><b>${escapeHtml(r.label)}</b><small>${escapeHtml(r.meta||objectConfig[r.type].label)}</small></div><i>→</i></button>`).join(""):`<p class="empty-state">No related objects yet.</p>`}</div></section>
      <section class="drawer-section"><div class="drawer-section-head"><h2>Actions</h2><button data-add-action>＋ Add action</button></div><form class="quick-action-form" id="quickActionForm" data-key="${escapeHtml(key)}" hidden><input name="title" required placeholder="What needs to happen?"><div><select name="assignee">${state.users.map(u=>`<option>${u.name}</option>`).join("")}</select><input name="due" placeholder="Due date"><button class="button primary">Add</button></div></form><div class="action-list">${actions.length?actions.map(a=>`<label class="action-item"><input type="checkbox" data-action-toggle="${a.id}" data-key="${escapeHtml(key)}" ${a.status==="Done"?"checked":""}><span><b>${escapeHtml(a.title)}</b><small>${objectRef("user",idByName("user",a.assignee),a.assignee)} · Due ${escapeHtml(a.due)}</small></span><em class="priority-dot ${a.priority.toLowerCase()}">${a.priority}</em></label>`).join(""):`<p class="empty-state">No open actions. Add the first next step.</p>`}</div></section>
      <section class="drawer-section"><div class="drawer-section-head"><h2>Comments & activity</h2><span>${comments.length} comments</span></div><div class="comment-list">${comments.map(c=>`<article class="comment"><button data-object-type="user" data-object-id="${idByName("user",c.author)}">${c.initials}</button><div><p><b>${escapeHtml(c.author)}</b><time>${c.time}</time></p><div>${renderMentionText(c.text)}</div></div></article>`).join("")}<article class="activity-event"><span>↗</span><p><b>${escapeHtml(objectName(type,object))}</b> was updated <time>recently</time></p></article></div><form class="comment-form" id="commentForm" data-key="${escapeHtml(key)}"><span>CM</span><div><textarea name="comment" required placeholder="Write a comment… Use @ to mention a teammate"></textarea><footer><small>@ Mention</small><button>Comment</button></footer></div></form></section>
    </div>`;
  document.querySelector("#objectBackdrop").hidden=false;document.querySelector("#objectDrawer").classList.add("open");document.querySelector("#objectDrawer").setAttribute("aria-hidden","false");
}
function navigateObject(type,id){const spec=`${type}:${id}`,params=new URLSearchParams();if(["issue","bill"].includes(state.route)&&parseHash().id)params.set("id",parseHash().id);params.set("object",spec);const next=`${state.route}?${params}`;if(location.hash.slice(1)===next)renderObjectDrawer(type,String(id));else location.hash=next;}
function closeObjectDrawer(updateHash=true){document.querySelector("#objectBackdrop").hidden=true;document.querySelector("#objectDrawer").classList.remove("open");document.querySelector("#objectDrawer").setAttribute("aria-hidden","true");if(updateHash&&parseHash().object)location.hash=["issue","bill"].includes(state.route)&&parseHash().id?`${state.route}?id=${encodeURIComponent(parseHash().id)}`:state.route;}

const renderers={dashboard:renderDashboard,issues:renderIssues,issue:renderIssueWorkspace,bill:renderBillWorkspace,clients:renderClients,keywords:renderKeywords,search:renderSearch,reports:renderReports,settings:renderSettings};
function render(){
  if(!renderers[state.route]) state.route="dashboard";
  app.innerHTML=renderers[state.route]();
  const activeIssue=state.route==="issue"?state.issues.find(item=>String(item.id)===String(parseHash().id)):null,activeBill=state.route==="bill"?getObject("bill",parseHash().id):null;
  document.querySelector("#crumbTitle").textContent=activeIssue?.name||activeBill?.id||pageMeta[state.route][0];
  document.querySelectorAll(".nav-link").forEach(x=>x.classList.toggle("active",x.dataset.route===(state.route==="issue"?"issues":state.route)));
  document.querySelector("#sidebar").classList.remove("open");
  const spec=parseHash().object;if(spec){const separator=spec.indexOf(":");renderObjectDrawer(spec.slice(0,separator),spec.slice(separator+1));}else closeObjectDrawer(false);
}

const fieldTemplates={
  issue:x=>`<div class="form-grid"><label class="full">Issue name<input name="name" required value="${escapeHtml(x?.name||"")}" placeholder="e.g. Housing & Real Estate"></label><label>Type<select name="type"><option ${x?.type==="Industry"?"selected":""}>Industry</option><option ${x?.type==="Issue"?"selected":""}>Issue</option></select></label><label>Color<select name="color"><option value="sage">Sage</option><option value="blue">Blue</option><option value="lavender">Lavender</option><option value="mint">Mint</option><option value="peach">Peach</option></select></label><label class="full">Description<textarea name="description" required placeholder="What policy area does this issue cover?">${escapeHtml(x?.description||"")}</textarea></label><label class="full">Themes<input name="themes" value="${escapeHtml(x?.themes?.join(", ")||"")}" placeholder="Separate theme names with commas"></label><label class="full">Associated clients<input name="clients" value="${escapeHtml(x?.clients?.join(", ")||"")}" placeholder="Separate client names with commas"></label></div>`,
  theme:x=>`<div class="form-grid"><label class="full">Theme name<input name="name" required value="${escapeHtml(x?.name||"")}" placeholder="e.g. Algorithmic Pricing and Rent Coordination"></label><label class="full">Related issues<input name="issues" required value="${escapeHtml(x?.issues?.join(", ")||"")}" placeholder="Separate issue names with commas"></label><label>Color<select name="color"><option value="sage">Sage</option><option value="purple">Purple</option><option value="blue">Blue</option><option value="mint">Mint</option><option value="peach">Peach</option><option value="sand">Sand</option></select></label><label class="full">Description<textarea name="description" required placeholder="What policy concept does this theme represent?">${escapeHtml(x?.description||"")}</textarea></label></div>`,
  "client-profile":x=>`<div class="form-grid"><label class="full">Profile name<input name="name" required value="${escapeHtml(x?.name||"")}"></label><label>Industry<input name="industry" required value="${escapeHtml(x?.industry||"")}"></label><label>Status<select name="status"><option ${x?.status==="Verified"?"selected":""}>Verified</option><option ${x?.status==="Needs review"?"selected":""}>Needs review</option></select></label><label class="full">Markets<input name="markets" value="${escapeHtml(x?.markets?.join(", ")||"")}" placeholder="Separate markets with commas"></label><label class="full">Products and services<input name="products" value="${escapeHtml(x?.products?.join(", ")||"")}" placeholder="Separate items with commas"></label><label class="full">Key competencies<input name="competencies" value="${escapeHtml(x?.competencies?.join(", ")||"")}" placeholder="Separate competencies with commas"></label><label class="full">Regulatory exposure<input name="regulatoryExposure" value="${escapeHtml(x?.regulatoryExposure?.join(", ")||"")}" placeholder="Separate policy exposures with commas"></label><label class="full">Strategic priorities<input name="priorities" value="${escapeHtml(x?.priorities?.join(", ")||"")}" placeholder="Separate priorities with commas"></label><label class="full">Sources<input name="sources" value="${escapeHtml(x?.sources?.join(", ")||"")}" placeholder="Separate sources with commas"></label></div>`,
  client:x=>`<div class="form-grid"><label class="full">Client name<input name="name" required value="${escapeHtml(x?.name||"")}" placeholder="Organization name"></label><label>Industry<input name="industry" required value="${escapeHtml(x?.industry||"")}" placeholder="e.g. Financial Services"></label><label>Relationship owner<input name="owner" required value="${escapeHtml(x?.owner||"")}" placeholder="Team member"></label><label class="full">Issues<input name="issues" value="${escapeHtml(x?.issues?.join(", ")||"")}" placeholder="Separate issue names with commas"></label></div>`,
  keyword:x=>`<div class="form-grid"><label class="full">Keyword or phrase<input name="term" required value="${escapeHtml(x?.term||"")}" placeholder="e.g. automated decision system"></label><label>Match type<select name="match"><option ${x?.match==="Contains"?"selected":""}>Contains</option><option ${x?.match==="Exact phrase"?"selected":""}>Exact phrase</option></select></label><label>Tracking scope<select name="groupType"><option ${x?.groupType==="Issue"?"selected":""}>Issue</option><option ${x?.groupType==="Client"?"selected":""}>Client</option><option ${x?.groupType==="Standalone"?"selected":""}>Standalone</option></select></label><label class="full">Issue or client name<input name="group" value="${escapeHtml(x?.group==="Standalone"?"":x?.group||"")}" placeholder="Optional for standalone keywords"></label><label class="full">Themes<input name="themes" value="${escapeHtml(x?.themes?.join(", ")||"")}" placeholder="Separate theme names with commas"></label></div>`
};

function openModal(type,id,context={}){
  const list=collectionFor(type), item=id?list.find(x=>String(x.id)===String(id)):null,displayType=objectConfig[type]?.label||type;
  const seed=!item&&type==="client-profile"&&context.client?{name:`${context.client} impact profile`,industry:state.clients.find(client=>client.name===context.client)?.industry||"",status:"Needs review",markets:[],products:[],competencies:[],regulatoryExposure:[],priorities:[],sources:[]}:null;
  state.editing={type,id:item?.id||null,client:context.client||item?.client};
  document.querySelector("#modalEyebrow").textContent=item?`EDIT ${displayType.toUpperCase()}`:`NEW ${displayType.toUpperCase()}`;
  document.querySelector("#modalTitle").textContent=item?`Edit ${displayType.toLowerCase()}`:context.client?`Create an AI profile for ${context.client}`:`Create a ${displayType.toLowerCase()}`;
  document.querySelector("#modalSubmit").textContent=item?"Save changes":`Create ${displayType.toLowerCase()}`;
  document.querySelector("#modalFields").innerHTML=fieldTemplates[type](item||seed);
  document.querySelector("#entityModal").showModal();
}

function saveEntity(form){
  const data=Object.fromEntries(new FormData(form)); const {type,id}=state.editing; const list=collectionFor(type);
  const previousName=id?list.find(x=>x.id===id)?.name:null;
  if(type==="issue") Object.assign(data,{clients:data.clients.split(",").map(x=>x.trim()).filter(Boolean),themes:data.themes.split(",").map(x=>x.trim()).filter(Boolean),bills:id?undefined:0,alerts:id?undefined:0,updated:"Just now",color:data.color||"sage"});
  if(type==="theme") Object.assign(data,{issues:data.issues.split(",").map(x=>x.trim()).filter(Boolean),color:data.color||"sage"});
  if(type==="client-profile") Object.assign(data,{client:state.editing.client,markets:data.markets.split(",").map(x=>x.trim()).filter(Boolean),products:data.products.split(",").map(x=>x.trim()).filter(Boolean),competencies:data.competencies.split(",").map(x=>x.trim()).filter(Boolean),regulatoryExposure:data.regulatoryExposure.split(",").map(x=>x.trim()).filter(Boolean),priorities:data.priorities.split(",").map(x=>x.trim()).filter(Boolean),sources:data.sources.split(",").map(x=>x.trim()).filter(Boolean),version:(list.find(x=>x.id===id)?.version||0)+1,lastReviewed:"Just now",completeness:95});
  if(type==="client") Object.assign(data,{issues:data.issues.split(",").map(x=>x.trim()).filter(Boolean),initials:initials(data.name),bills:id?undefined:0,activity:"Just now",color:"green"});
  if(type==="keyword") Object.assign(data,{group:data.group||"Standalone",themes:data.themes.split(",").map(x=>x.trim()).filter(Boolean),hits:id?undefined:0,trend:id?undefined:0});
  if(id){const item=list.find(x=>x.id===id);Object.keys(data).forEach(k=>data[k]!==undefined&&(item[k]=data[k]));} else {data.id=type==="client-profile"?`${data.client.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")}-v1`:Math.max(0,...list.map(x=>x.id))+1;list.unshift(data);}
  if(type==="theme")state.issues.forEach(issue=>{issue.themes=issue.themes.filter(name=>name!==previousName&&name!==data.name);if(data.issues.includes(issue.name))issue.themes.push(data.name);});
  if(type==="client-profile")state.impactAssessments.filter(assessment=>assessment.profile===id).forEach(assessment=>assessment.reviewStatus="Stale");
  document.querySelector("#entityModal").close(); render(); showToast(id?`${type[0].toUpperCase()+type.slice(1)} updated`:`${type[0].toUpperCase()+type.slice(1)} created`);
}

document.addEventListener("click",e=>{
  if(e.target.closest("[data-open-sessions]")){renderSessionDialog();return;}
  if(e.target.closest("[data-close-sessions]")){document.querySelector("#sessionModal").close();return;}
  const sessionFilterButton=e.target.closest("[data-session-filter]");if(sessionFilterButton){sessionFilter=sessionFilterButton.dataset.sessionFilter;document.querySelectorAll("[data-session-filter]").forEach(button=>button.classList.toggle("active",button===sessionFilterButton));filterSessionRows();return;}
  const assessmentDecision=e.target.closest("[data-assessment-decision]");if(assessmentDecision){const assessment=getObject("impact-assessment",assessmentDecision.dataset.id);assessment.reviewStatus=assessmentDecision.dataset.assessmentDecision;renderObjectDrawer("impact-assessment",assessment.id);showToast(`Assessment ${assessment.reviewStatus.toLowerCase()}`);return;}
  const openIssue=e.target.closest("[data-open-issue]");if(openIssue){Object.assign(state.issueWorkspace,{theme:"All themes",client:"All clients",view:"high-level",state:"All states",columnsOpen:false,updatesOpen:false,updateFilter:"All updates"});location.hash=`issue?id=${openIssue.dataset.openIssue}`;return;}
  const issueView=e.target.closest("[data-issue-view]");if(issueView){state.issueWorkspace.view=issueView.dataset.issueView;state.issueWorkspace.columnsOpen=false;render();return;}
  if(e.target.closest("[data-open-issue-updates]")){state.issueWorkspace.updatesOpen=true;render();return;}
  if(e.target.closest("[data-close-issue-updates]")){state.issueWorkspace.updatesOpen=false;render();return;}
  const updateFilter=e.target.closest("[data-update-filter]");if(updateFilter){state.issueWorkspace.updateFilter=updateFilter.dataset.updateFilter;render();return;}
  const reviewUpdate=e.target.closest("[data-review-update]");if(reviewUpdate){if(!state.issueWorkspace.reviewedUpdates.includes(reviewUpdate.dataset.reviewUpdate))state.issueWorkspace.reviewedUpdates.push(reviewUpdate.dataset.reviewUpdate);render();showToast("Update marked as reviewed");return;}
  if(e.target.closest("[data-mark-issue-reviewed]")){const issue=state.issues.find(item=>String(item.id)===String(parseHash().id))||state.issues[1];state.issueWorkspace.reviewedUpdates=[...new Set([...state.issueWorkspace.reviewedUpdates,...issueChangeEvents(issue).map(event=>event.id)])];render();showToast("All issue updates reviewed");return;}
  if(e.target.closest("[data-apply-live-updates]")){const issue=state.issues.find(item=>String(item.id)===String(parseHash().id));if(issue&&!state.issueWorkspace.liveUpdatesApplied.includes(issue.id)){state.issueWorkspace.liveUpdatesApplied.push(issue.id);issue.updated="Just now";}render();showToast("Issue refreshed with the latest changes");return;}
  const openBillTab=e.target.closest("[data-open-bill-tab]");if(openBillTab){closeObjectDrawer(false);state.billWorkspace.tab=openBillTab.dataset.openBillTab;location.hash=`bill?id=${encodeURIComponent(openBillTab.dataset.billId)}`;return;}
  const billTab=e.target.closest("[data-bill-tab]");if(billTab){state.billWorkspace.tab=billTab.dataset.billTab;render();return;}
  if(e.target.closest("[data-bill-back]")){history.back();return;}
  const heatState=e.target.closest("[data-heat-state]");if(heatState){state.issueWorkspace.state=state.issueWorkspace.state===heatState.dataset.heatState?"All states":heatState.dataset.heatState;render();return;}
  if(e.target.closest("[data-clear-state]")){state.issueWorkspace.state="All states";render();return;}
  if(e.target.closest("[data-toggle-columns]")){state.issueWorkspace.columnsOpen=!state.issueWorkspace.columnsOpen;render();return;}
  if(e.target.closest("[data-add-view]")){const name=prompt("Name this view");if(name?.trim()){const base=activeIssueView(),id=`custom-${Date.now()}`;state.issueWorkspace.customViews.push({id,name:name.trim(),base});state.issueWorkspace.columns[id]=[...(state.issueWorkspace.columns[state.issueWorkspace.view]||state.issueWorkspace.columns[base])];state.issueWorkspace.view=id;render();showToast("View created");}return;}
  const startProfile=e.target.closest("[data-start-profile]");if(startProfile){openModal("client-profile",null,{client:startProfile.dataset.startProfile});return;}
  const objectLink=e.target.closest("[data-object-type]");if(objectLink){navigateObject(objectLink.dataset.objectType,objectLink.dataset.objectId);return;}
  if(e.target.closest("[data-close-object]")||e.target.id==="objectBackdrop"){closeObjectDrawer();return;}
  if(e.target.closest("[data-copy-object]")){navigator.clipboard?.writeText(location.href);showToast("Object link copied");}
  if(e.target.closest("[data-follow-object]")){const button=e.target.closest("[data-follow-object]");button.textContent="★ Following";showToast("You’re now following this object");}
  const fullObject=e.target.closest("[data-full-object]");if(fullObject){if(fullObject.dataset.type==="issue"){closeObjectDrawer(false);location.hash=`issue?id=${fullObject.dataset.id}`;}else if(fullObject.dataset.type==="bill"){closeObjectDrawer(false);state.billWorkspace.tab="overview";location.hash=`bill?id=${encodeURIComponent(fullObject.dataset.id)}`;}else showToast("Full-page object view is next in the build sequence");return;}
  if(e.target.closest("[data-add-action]")){document.querySelector("#quickActionForm").hidden=false;document.querySelector("#quickActionForm input")?.focus();}
  const editObject=e.target.closest("[data-edit-object]");if(editObject){closeObjectDrawer(false);openModal(editObject.dataset.type,editObject.dataset.id);return;}
  const route=e.target.closest("[data-route]"); if(route){state.route=route.dataset.route;}
  const add=e.target.closest("[data-add]"); if(add&&add.dataset.add!=="report") openModal(add.dataset.add);
  const edit=e.target.closest("[data-edit]"); if(edit) openModal(edit.dataset.edit,edit.dataset.id);
  const del=e.target.closest("[data-delete]"); if(del&&confirm(`Delete this ${del.dataset.delete}?`)){const key=`${del.dataset.delete}s`;state[key]=state[key].filter(x=>x.id!==Number(del.dataset.id));render();showToast(`${del.dataset.delete[0].toUpperCase()+del.dataset.delete.slice(1)} deleted`);}
  if(e.target.closest("[data-close-modal]")){document.querySelector("#entityModal").close();const spec=parseHash().object;if(spec){const separator=spec.indexOf(":");renderObjectDrawer(spec.slice(0,separator),spec.slice(separator+1));}}
  const alertFilter=e.target.closest("[data-alert-filter]"); if(alertFilter){state.dashboardFilter=alertFilter.dataset.alertFilter;render();}
  if(e.target.closest("[data-mark-read]")) showToast("All alerts marked as read");
  if(e.target.closest("[data-add='report']")) showToast("New report builder opened");
  if(e.target.closest("[data-report-open]")) showToast("Report opened");
  if(e.target.closest("[data-save-settings]")) showToast("Settings saved");
  if(e.target.closest("[data-setting-action]")) showToast(`${e.target.closest("[data-setting-action]").dataset.settingAction} opened`);
  if(e.target.closest("[data-issue-export]")) showToast("Current view prepared for export");
  if(e.target.closest("[data-add-row]")) showToast("New state intelligence row opened");
  if(e.target.closest("[data-compare-versions]")) showToast("Version comparison opened");
  if(e.target.closest("[data-run-impact]")) showToast("Client impact assessment started");
  if(e.target.closest("[data-page-add-action]")) showToast("New bill action opened");
  const billPreview=e.target.closest("[data-bill-preview]");if(billPreview){const id=billPreview.dataset.billPreview,issue=state.issues.find(item=>String(item.id)===String(parseHash().id))||state.issues[0],code=id.split(" ")[0];if(!getObject("bill",id))bills.push({id,state:code,title:`${issue.name} requirements`,summary:`Establishes state requirements related to ${issue.name.toLowerCase()} and covered entity obligations.`,status:"In committee",statusType:"warning",date:"Jul 16",issues:[issue.name],themes:[...issue.themes],clients:[...issue.clients],sponsor:state.legislators.find(item=>item.jurisdiction===stateSession(code)?.name)?.name||"Sponsor pending"});navigateObject("bill",id);return;}
  if(e.target.closest("[data-clear-search]")){document.querySelector("#billSearchInput").value="";filterBills("");}
  if(e.target.closest(".track-button")){e.target.closest(".track-button").textContent="✓ Tracked";e.target.closest(".track-button").classList.add("tracked");showToast("Bill added to your tracker");}
});
document.addEventListener("input",e=>{if(e.target.matches("[data-list-search]")){const q=e.target.value.toLowerCase();document.querySelectorAll(".searchable").forEach(x=>x.hidden=!x.dataset.search.includes(q));}if(e.target.id==="sessionSearch")filterSessionRows();});
document.addEventListener("change",e=>{
  if(e.target.matches("[data-workspace-filter]")){state.issueWorkspace[e.target.dataset.workspaceFilter]=e.target.value;state.issueWorkspace.state="All states";render();return;}
  if(e.target.matches("[data-column-key]")){const ws=state.issueWorkspace,base=activeIssueView(),key=ws.view,columns=ws.columns[key]||(ws.columns[key]=[...ws.columns[base]]),column=e.target.dataset.columnKey;if(e.target.checked&&!columns.includes(column))columns.push(column);if(!e.target.checked&&columns.length>1)ws.columns[key]=columns.filter(item=>item!==column);render();return;}
  if(e.target.matches("[data-object-priority]")){state.collaboration.priorities[e.target.dataset.key]=e.target.value;showToast(`Priority set to ${e.target.value}`);}
  if(e.target.matches("[data-action-toggle]")){const action=(state.collaboration.actions[e.target.dataset.key]||[]).find(a=>a.id===Number(e.target.dataset.actionToggle));if(action){action.status=e.target.checked?"Done":"Open";e.target.closest(".action-item").classList.toggle("done",e.target.checked);showToast(e.target.checked?"Action completed":"Action reopened");}}
});
document.querySelector("#entityForm").addEventListener("submit",e=>{e.preventDefault();saveEntity(e.currentTarget);});
document.querySelector("#openMenu").addEventListener("click",()=>document.querySelector("#sidebar").classList.add("open"));
document.querySelector("#closeMenu").addEventListener("click",()=>document.querySelector("#sidebar").classList.remove("open"));
document.querySelector("#globalSearch").addEventListener("click",()=>{location.hash="search";state.route="search";render();setTimeout(()=>document.querySelector("#billSearchInput")?.focus(),0);});
document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();document.querySelector("#globalSearch").click();}if(e.key==="Escape"&&document.querySelector("#objectDrawer").classList.contains("open"))closeObjectDrawer();});
window.addEventListener("hashchange",()=>{state.route=parseHash().route||"dashboard";render();});
document.addEventListener("submit",e=>{
  if(e.target.id==="billSearch"){e.preventDefault();filterBills(document.querySelector("#billSearchInput").value);}
  if(e.target.id==="quickActionForm"){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),key=e.target.dataset.key;state.collaboration.actions[key]??=[];state.collaboration.actions[key].push({id:Date.now(),title:data.title,assignee:data.assignee,due:data.due||"No date",status:"Open",priority:state.collaboration.priorities[key]||"Normal"});const [type,...rest]=key.split(":");renderObjectDrawer(type,rest.join(":"));showToast("Action added");}
  if(e.target.id==="commentForm"){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),key=e.target.dataset.key;state.collaboration.comments[key]??=[];state.collaboration.comments[key].push({author:"Connor Matthews",initials:"CM",time:"Just now",text:data.comment});const [type,...rest]=key.split(":");renderObjectDrawer(type,rest.join(":"));showToast("Comment posted");}
});
function filterBills(query){const q=query.toLowerCase().trim();let count=0;document.querySelectorAll("#billResults .searchable").forEach(x=>{const show=!q||x.dataset.search.includes(q);x.hidden=!show;if(show)count++;});document.querySelector("#searchResultCount").textContent=count;}

render();
